class Solution {
public:
    vector<int> diStringMatch(string s) {
        int low = 0, high = static_cast<int>(s.size());
        vector<int> perm;
        perm.reserve(s.size() + 1);

        for (char c : s) {
            if (c == 'I') {
                perm.push_back(low++);
            } else {
                perm.push_back(high--);
            }
        }

        perm.push_back(low);
        return perm;
    }
};
